import {
  buildDraftLibraryExport,
  createDesktopCompanionSyncState,
  createWorkspaceBundle,
  type DesktopCompanionSyncSource,
  parseDesktopCompanionSyncState,
  parseWorkspaceBundle,
  type Draft,
  type DesktopCompanionSyncState,
  type WorkspaceBundleTemplateRecord,
} from '@char-gen/shared';
import { configManager } from './config/manager.js';
import { getDesktopCompanionIdentity } from './desktop-companion-settings.js';
import { isDesktopRuntime } from './runtime.js';
import { DraftStorage } from './storage/draft-db.js';
import {
  getBlueprintOverrides,
  getStoredTemplates,
  saveBlueprintOverrides,
  saveStoredTemplates,
  type StoredTemplateRecord,
} from './templates/browser.js';

export interface WorkspaceBundleImportResult {
  drafts: number;
  remappedDrafts: number;
  templates: number;
  blueprintOverrides: number;
  configImported: boolean;
  apiKeys: number;
}

export interface DesktopCompanionSyncPreview {
  exportedAt: string;
  source?: DesktopCompanionSyncSource;
  domains: {
    drafts: {
      incomingCount: number;
      matchingReviewIds: number;
      newReviewIds: number;
      overlappingDrafts: Array<{
        reviewId: string;
        incomingName: string;
        currentName: string;
      }>;
      newDrafts: Array<{
        reviewId: string;
        incomingName: string;
      }>;
    };
    config: {
      hasConfig: boolean;
      hasApiKeys: boolean;
      incomingModel: string | null;
      currentModel: string | null;
      modelChanged: boolean;
    };
    templates: {
      incomingCount: number;
      matchingNames: number;
      newNames: number;
      overlappingTemplateNames: string[];
      newTemplateNames: string[];
    };
    blueprints: {
      incomingCount: number;
      matchingPaths: number;
      newPaths: number;
      overlappingBlueprintPaths: string[];
      newBlueprintPaths: string[];
    };
  };
}

function buildSyncStatePayload(options: { includeApiKeys?: boolean } = {}) {
  const { api_keys: _ignoredApiKeys, ...config } = configManager.getConfig();

  return {
    config: {
      config,
      ...(options.includeApiKeys === false ? {} : { api_keys: configManager.getApiKeys() }),
    },
    templates: getStoredTemplates().map(cloneTemplateRecord),
    blueprints: getBlueprintOverrides(),
  };
}

function cloneTemplateRecord(record: StoredTemplateRecord): WorkspaceBundleTemplateRecord {
  return JSON.parse(JSON.stringify(record)) as WorkspaceBundleTemplateRecord;
}

function mergeTemplateRecords(
  existing: StoredTemplateRecord[],
  incoming: readonly WorkspaceBundleTemplateRecord[],
): StoredTemplateRecord[] {
  const byName = new Map(existing.map((record) => [record.template.name, record] as const));

  for (const record of incoming) {
    byName.set(record.template.name, JSON.parse(JSON.stringify(record)) as StoredTemplateRecord);
  }

  return Array.from(byName.values());
}

export async function exportWorkspaceBundleText(options: { includeApiKeys?: boolean } = {}): Promise<string> {
  const exportedDrafts = JSON.parse(await DraftStorage.exportAll()) as { drafts?: Draft[] };
  const syncPayload = buildSyncStatePayload(options);

  const bundle = createWorkspaceBundle({
    drafts: Array.isArray(exportedDrafts.drafts) ? exportedDrafts.drafts : [],
    ...(syncPayload.config.config ? { config: syncPayload.config.config } : {}),
    ...(syncPayload.config.api_keys ? { api_keys: syncPayload.config.api_keys } : {}),
    templates: syncPayload.templates,
    blueprint_overrides: syncPayload.blueprints,
  }, {
    platform: isDesktopRuntime() ? 'desktop' : 'web',
    runtime: isDesktopRuntime() ? 'tauri' : 'browser',
  });

  return JSON.stringify(bundle, null, 2);
}

export async function exportDesktopCompanionSyncStateText(options: { includeApiKeys?: boolean } = {}): Promise<string> {
  const exportedDrafts = JSON.parse(await DraftStorage.exportAll()) as { drafts?: Draft[] };
  const identity = getDesktopCompanionIdentity();
  const syncState = createDesktopCompanionSyncState({
    drafts: Array.isArray(exportedDrafts.drafts) ? exportedDrafts.drafts : [],
    ...buildSyncStatePayload(options),
  }, {
    deviceId: identity.deviceId,
    name: identity.name,
    platform: isDesktopRuntime() ? 'desktop' : 'web',
    runtime: isDesktopRuntime() ? 'tauri' : 'browser',
  });

  return JSON.stringify(syncState, null, 2);
}

async function importDesktopCompanionSyncState(syncState: DesktopCompanionSyncState): Promise<WorkspaceBundleImportResult> {
  const draftImport = syncState.payload.drafts && syncState.payload.drafts.length > 0
    ? await DraftStorage.import(buildDraftLibraryExport(syncState.payload.drafts), { conflictStrategy: 'merge' })
    : { imported: 0, remapped: 0 };

  const configPayload = syncState.payload.config;
  if (configPayload?.config) {
    configManager.importConfig(JSON.stringify({ config: configPayload.config }));
  }

  if (configPayload?.api_keys) {
    configManager.importApiKeys(JSON.stringify(configPayload.api_keys));
  }

  if (syncState.payload.templates && syncState.payload.templates.length > 0) {
    const mergedTemplates = mergeTemplateRecords(getStoredTemplates(), syncState.payload.templates);
    saveStoredTemplates(mergedTemplates);
  }

  if (syncState.payload.blueprints && Object.keys(syncState.payload.blueprints).length > 0) {
    saveBlueprintOverrides({
      ...getBlueprintOverrides(),
      ...syncState.payload.blueprints,
    });
  }

  return {
    drafts: draftImport.imported,
    remappedDrafts: draftImport.remapped,
    templates: syncState.payload.templates?.length ?? 0,
    blueprintOverrides: Object.keys(syncState.payload.blueprints ?? {}).length,
    configImported: Boolean(configPayload?.config),
    apiKeys: Object.keys(configPayload?.api_keys ?? {}).length,
  };
}

export async function importDesktopCompanionSyncStateText(raw: string): Promise<WorkspaceBundleImportResult> {
  return importDesktopCompanionSyncState(parseDesktopCompanionSyncState(raw));
}

export async function previewDesktopCompanionSyncStateText(raw: string): Promise<DesktopCompanionSyncPreview> {
  const syncState = parseDesktopCompanionSyncState(raw);
  const localDraftMetadata = await DraftStorage.getAllMetadata({ includeArchived: true });
  const localDraftsById = new Map(localDraftMetadata.map((draft) => [draft.review_id, draft] as const));
  const localDraftIds = new Set(localDraftsById.keys());
  const localTemplateNames = new Set(getStoredTemplates().map((record) => record.template.name));
  const localBlueprintPaths = new Set(Object.keys(getBlueprintOverrides()));
  const incomingDrafts = syncState.payload.drafts ?? [];
  const incomingTemplates = syncState.payload.templates ?? [];
  const incomingBlueprints = Object.keys(syncState.payload.blueprints ?? {});
  const incomingConfig = syncState.payload.config;
  const currentConfig = configManager.getConfig();

  const matchingReviewIds = incomingDrafts.filter((draft) => localDraftIds.has(draft.metadata.review_id)).length;
  const matchingTemplateNames = incomingTemplates.filter((record) => localTemplateNames.has(record.template.name)).length;
  const matchingBlueprintPaths = incomingBlueprints.filter((path) => localBlueprintPaths.has(path)).length;
  const overlappingDrafts = incomingDrafts
    .filter((draft) => localDraftIds.has(draft.metadata.review_id))
    .map((draft) => {
      const localDraft = localDraftsById.get(draft.metadata.review_id);
      return {
        reviewId: draft.metadata.review_id,
        incomingName: draft.metadata.character_name || draft.metadata.seed,
        currentName: localDraft?.character_name || localDraft?.seed || draft.metadata.review_id,
      };
    });
  const newDrafts = incomingDrafts
    .filter((draft) => !localDraftIds.has(draft.metadata.review_id))
    .map((draft) => ({
      reviewId: draft.metadata.review_id,
      incomingName: draft.metadata.character_name || draft.metadata.seed,
    }));
  const overlappingTemplateNames = incomingTemplates
    .map((record) => record.template.name)
    .filter((name) => localTemplateNames.has(name));
  const newTemplateNames = incomingTemplates
    .map((record) => record.template.name)
    .filter((name) => !localTemplateNames.has(name));
  const overlappingBlueprintPaths = incomingBlueprints.filter((path) => localBlueprintPaths.has(path));
  const newBlueprintPaths = incomingBlueprints.filter((path) => !localBlueprintPaths.has(path));
  const incomingModel = incomingConfig?.config?.model ?? null;
  const currentModel = currentConfig.model || null;

  return {
    exportedAt: syncState.exportedAt,
    ...(syncState.source ? { source: syncState.source } : {}),
    domains: {
      drafts: {
        incomingCount: incomingDrafts.length,
        matchingReviewIds,
        newReviewIds: Math.max(0, incomingDrafts.length - matchingReviewIds),
        overlappingDrafts,
        newDrafts,
      },
      config: {
        hasConfig: Boolean(incomingConfig?.config),
        hasApiKeys: Boolean(incomingConfig?.api_keys && Object.keys(incomingConfig.api_keys).length > 0),
        incomingModel,
        currentModel,
        modelChanged: Boolean(incomingModel && currentModel && incomingModel !== currentModel),
      },
      templates: {
        incomingCount: incomingTemplates.length,
        matchingNames: matchingTemplateNames,
        newNames: Math.max(0, incomingTemplates.length - matchingTemplateNames),
        overlappingTemplateNames,
        newTemplateNames,
      },
      blueprints: {
        incomingCount: incomingBlueprints.length,
        matchingPaths: matchingBlueprintPaths,
        newPaths: Math.max(0, incomingBlueprints.length - matchingBlueprintPaths),
        overlappingBlueprintPaths,
        newBlueprintPaths,
      },
    },
  };
}

export async function importWorkspaceBundleText(raw: string): Promise<WorkspaceBundleImportResult> {
  const bundle = parseWorkspaceBundle(raw);

  const draftImport = bundle.payload.drafts.length > 0
    ? await DraftStorage.import(buildDraftLibraryExport(bundle.payload.drafts), { conflictStrategy: 'merge' })
    : { imported: 0, remapped: 0 };

  if (bundle.payload.config) {
    configManager.importConfig(JSON.stringify({ config: bundle.payload.config }));
  }

  if (bundle.payload.api_keys) {
    configManager.importApiKeys(JSON.stringify(bundle.payload.api_keys));
  }

  if (bundle.payload.templates && bundle.payload.templates.length > 0) {
    const mergedTemplates = mergeTemplateRecords(getStoredTemplates(), bundle.payload.templates);
    saveStoredTemplates(mergedTemplates);
  }

  if (bundle.payload.blueprint_overrides && Object.keys(bundle.payload.blueprint_overrides).length > 0) {
    saveBlueprintOverrides({
      ...getBlueprintOverrides(),
      ...bundle.payload.blueprint_overrides,
    });
  }

  return {
    drafts: draftImport.imported,
    remappedDrafts: draftImport.remapped,
    templates: bundle.payload.templates?.length ?? 0,
    blueprintOverrides: Object.keys(bundle.payload.blueprint_overrides ?? {}).length,
    configImported: Boolean(bundle.payload.config),
    apiKeys: Object.keys(bundle.payload.api_keys ?? {}).length,
  };
}